let coepCredentialless = false; // Başlangıç değeri false

self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

self.addEventListener("message", (event) => {
    if (event.data) {
        if (event.data.type === "deregister") {
            self.registration.unregister()
                .then(() => self.clients.matchAll())
                .then((clients) => {
                    clients.forEach((client) => client.navigate(client.url));
                });
        } else if (event.data.type === "coepCredentialless") {
            coepCredentialless = event.data.value;
        }
    }
});

self.addEventListener("fetch", (event) => {
    const originalRequest = event.request;

    if (originalRequest.cache === "only-if-cached" && originalRequest.mode !== "same-origin") {
        return;
    }

    const modifiedRequest = coepCredentialless && originalRequest.mode === "no-cors"
        ? new Request(originalRequest, { credentials: "omit" })
        : originalRequest;

    event.respondWith(
        fetch(modifiedRequest).then((response) => {
            if (response.ok) {
                const modifiedHeaders = new Headers(response.headers);
                modifiedHeaders.set("Cross-Origin-Opener-Policy", "same-origin");
                modifiedHeaders.set("Cross-Origin-Embedder-Policy", "require-corp");
                return new Response(response.body, {
                    status: response.status,
                    statusText: response.statusText,
                    headers: modifiedHeaders,
                });
            }
            return response;
        })
    );
});
